insert into TB_LGCL_REL_ATRB(LGCL_REL_ATRB_SN, LGCL_REL_SN, ORGNL_ATRB_SN, TRGT_ATRB_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL_ATRB'), r.LGCL_REL_SN, pm.LGCL_ATRB_SN, cm.LGCL_ATRB_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_LGCL_ATRB' join TB_COL cc on cc.TBL_SN = ct.TBL_SN and cc.COL_NM = 'ORGNL_ATRB_SN' join TB_COL pc on pc.TBL_SN = pt.TBL_SN and pc.COL_NM = 'LGCL_ATRB_SN' join TB_ATRB_COL_MPNG cm on cm.COL_SN = cc.COL_SN join TB_ATRB_COL_MPNG pm on pm.COL_SN = pc.COL_SN join TB_LGCL_REL r on r.PRJ_SN = 0 and r.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'ORGNL_ATRB_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조' where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_LGCL_REL_ATRB' and not exists (select 1 from TB_LGCL_REL_ATRB x where x.LGCL_REL_SN = r.LGCL_REL_SN);
insert into TB_TBL_REL(REL_SN, PRJ_SN, ORGNL_TBL_SN, TRGT_TBL_SN, REL_NM, REL_TYPE_CD, REL_SRC_CD, DRVN_COL_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_REL'), 0, o.TBL_SN, t.TBL_SN, 'FK_LGCL_REL_ATRB_03', 'FK', 'USER', null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL o join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_LGCL_ATRB' where o.PRJ_SN = 0 and o.TBL_NM = 'TB_LGCL_REL_ATRB' and not exists (select 1 from TB_TBL_REL r where r.PRJ_SN = 0 and r.ORGNL_TBL_SN = o.TBL_SN and upper(r.REL_NM) = 'FK_LGCL_REL_ATRB_03');
insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select nextval('SQ_TBL_REL_COL'), r.REL_SN, oc.COL_SN, tc.COL_SN, 1 from TB_TBL_REL r join TB_TBL o on o.TBL_SN = r.ORGNL_TBL_SN and o.PRJ_SN = 0 and o.TBL_NM = 'TB_LGCL_REL_ATRB' join TB_COL oc on oc.TBL_SN = r.ORGNL_TBL_SN and oc.COL_NM = 'TRGT_ATRB_SN' join TB_COL tc on tc.TBL_SN = r.TRGT_TBL_SN and tc.COL_NM = 'LGCL_ATRB_SN' where r.PRJ_SN = 0 and upper(r.REL_NM) = 'FK_LGCL_REL_ATRB_03' and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN and x.COL_ORD = 1);
insert into TB_LGCL_REL(LGCL_REL_SN, PRJ_SN, LGCL_MDL_SN, ORGNL_ENTT_SN, TRGT_ENTT_SN, REL_NM, REL_EXPLN, IDNTF_YN, ORGNL_MIN_CNT, ORGNL_MAX_CNT, TRGT_MIN_CNT, TRGT_MAX_CNT, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL'), 0, pe.LGCL_MDL_SN, pe.LGCL_ENTT_SN, ce.LGCL_ENTT_SN, pt.TBL_KORN_NM, ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'TRGT_ATRB_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조', case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('TRGT_ATRB_SN') and c.PK_YN = false) then false else true end, case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('TRGT_ATRB_SN') and c.NULL_ALWNC_YN = true) then 0 else 1 end, 1, 0, null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_LGCL_ATRB' join TB_LGCL_ENTT ce on ce.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ce.ENTT_NM = ct.TBL_KORN_NM join TB_LGCL_ENTT pe on pe.LGCL_MDL_SN = ce.LGCL_MDL_SN and pe.ENTT_NM = pt.TBL_KORN_NM where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_LGCL_REL_ATRB' and not exists (select 1 from TB_LGCL_REL x where x.LGCL_MDL_SN = ce.LGCL_MDL_SN and x.ORGNL_ENTT_SN = pe.LGCL_ENTT_SN and x.TRGT_ENTT_SN = ce.LGCL_ENTT_SN and x.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'TRGT_ATRB_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조');
insert into TB_LGCL_REL_ATRB(LGCL_REL_ATRB_SN, LGCL_REL_SN, ORGNL_ATRB_SN, TRGT_ATRB_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL_ATRB'), r.LGCL_REL_SN, pm.LGCL_ATRB_SN, cm.LGCL_ATRB_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_LGCL_ATRB' join TB_COL cc on cc.TBL_SN = ct.TBL_SN and cc.COL_NM = 'TRGT_ATRB_SN' join TB_COL pc on pc.TBL_SN = pt.TBL_SN and pc.COL_NM = 'LGCL_ATRB_SN' join TB_ATRB_COL_MPNG cm on cm.COL_SN = cc.COL_SN join TB_ATRB_COL_MPNG pm on pm.COL_SN = pc.COL_SN join TB_LGCL_REL r on r.PRJ_SN = 0 and r.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'TRGT_ATRB_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조' where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_LGCL_REL_ATRB' and not exists (select 1 from TB_LGCL_REL_ATRB x where x.LGCL_REL_SN = r.LGCL_REL_SN);
