insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_IDX_COL'), i.IDX_SN, c.COL_SN, 1 from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'UX_LGCL_REL_ATRB_01' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'LGCL_REL_SN' where t.PRJ_SN = 0 and t.TBL_NM = 'TB_LGCL_REL_ATRB' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN and x.COL_ORD = 1);
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_IDX_COL'), i.IDX_SN, c.COL_SN, 2 from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'UX_LGCL_REL_ATRB_01' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'ORGNL_ATRB_SN' where t.PRJ_SN = 0 and t.TBL_NM = 'TB_LGCL_REL_ATRB' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN and x.COL_ORD = 2);
